import { verifyAdmin } from '../lib/auth';

// Test function to verify admin authentication logic
export async function testAdminAuth() {
  const result = await verifyAdmin();
  console.log('Admin verification result:', result);

  if (!result.isAdmin) {
    console.log('✅ Non-admin user correctly denied access');
  } else {
    console.log('❌ Admin user detected - this is expected for testing with admin users');
  }

  return result;
}

// Export for use in tests
export default testAdminAuth;

