          <h1 style={{
            fontSize: '2rem',
            fontWeight: 'bold',
            color: '#1e293b',
            margin: 0
          }}>
            Admin Dashboard
          </h1>
          <p style={{
            color: '#64748b',
            margin: '0.5rem 0 0 0'
          }}>
            Administrative area - restricted access
          </p>
        </header>

        <main>
          {children}
        </main>
      </div>
    </div>
  );
}

